from pypdf import PdfReader

path='/root/sc100-blank.pdf'
reader=PdfReader(path)
fields=reader.get_fields() or {}

# Map field object id to page index
page_fields=[]
for i, page in enumerate(reader.pages):
    annots=page.get('/Annots') or []
    for annot in annots:
        obj=annot.get_object()
        if '/T' in obj:
            name=obj['/T']
            rect=obj.get('/Rect')
            page_fields.append((name, i, rect))

# Print relevant fields sorted by page then y coordinate
for name, i, rect in sorted(page_fields, key=lambda x: (x[1], -(x[2][1] if x[2] else 0))):
    if any(key in name for key in [
        'Plaintiff', 'Defendant', 'Claim', 'FillField', 'Date', 'Checkbox', 'Zip', 'Email', 'Phone', 'Address', 'City', 'State', 'Zip'
    ]):
        print(i+1, name, rect)
