from pypdf import PdfReader, PdfWriter
from pypdf.generic import NameObject

src='/root/sc100-blank.pdf'
reader=PdfReader(src)
writer=PdfWriter()
writer.append_pages_from_reader(reader)

# set some checkbox values
values={
    'Checkbox50[0]': '/1',
    'Checkbox62[1]': '/2',
    'Checkbox5cb[0]': '/1',
}

# need to apply to all pages
for page in writer.pages:
    writer.update_page_form_field_values(page, values)

if '/AcroForm' in writer._root_object:
    writer._root_object['/AcroForm'].update({NameObject('/NeedAppearances'): True})

out='/tmp/test-filled.pdf'
with open(out,'wb') as f:
    writer.write(f)

# read back
r=PdfReader(out)
fields=r.get_fields() or {}
for key in values:
    # find full field names containing key
    for name, f in fields.items():
        if name.endswith(key):
            print(name, f.get('/V'), f.get('/AS'))
